from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor

# Set up.
prime_hub = PrimeHub()
Moter_E_Attachment = Motor(Port.E, Direction.CLOCKWISE)
Moter_left_wheel = Motor(Port.C, Direction.CLOCKWISE)
Moter_right_wheel = Motor(Port.D, Direction.CLOCKWISE)


# The main program starts here.
Moter_E_Attachment.run_angle(200, 270)
Moter_right_wheel.run_angle(500, 360)
Moter_E_Attachment.run_angle(200, -300)
